/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "model.h"

#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/schema/schema_generated.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define KWS_SMOKE_FEATURE_SIZE       (124 * 40 * 3)
#define KWS_SMOKE_CLASS_COUNT        5
#define KWS_SMOKE_DEFAULT_WARMUP     5
#define KWS_SMOKE_DEFAULT_REPEAT     50
#define KWS_SMOKE_MAX_REPEAT         200

/****************************************************************************
 * Private Data
 ****************************************************************************/

static alignas(16) uint8_t
  g_tensor_arena[CONFIG_SMART_HOME_KWS_SMOKE_ARENA_SIZE];
static uint32_t g_invoke_us[KWS_SMOKE_MAX_REPEAT];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void kws_smoke_usage(const char *program)
{
  printf("Usage: %s [--warmup N] [--repeat N]\n", program);
  printf("  --warmup N  Invokes excluded from timing (default: %d)\n",
         KWS_SMOKE_DEFAULT_WARMUP);
  printf("  --repeat N  Timed invokes, 1-%d (default: %d)\n",
         KWS_SMOKE_MAX_REPEAT, KWS_SMOKE_DEFAULT_REPEAT);
}

static int kws_smoke_parse_count(const char *text, unsigned int maximum,
                                 unsigned int *value)
{
  char *end;
  unsigned long parsed;

  if (text == NULL || value == NULL)
    {
      return -EINVAL;
    }

  errno = 0;
  parsed = strtoul(text, &end, 10);
  if (errno != 0 || end == text || *end != '\0' || parsed > maximum)
    {
      return -EINVAL;
    }

  *value = (unsigned int)parsed;
  return 0;
}

static int kws_smoke_parse_options(int argc, char *argv[],
                                   unsigned int *warmup,
                                   unsigned int *repeat)
{
  int index;

  *warmup = KWS_SMOKE_DEFAULT_WARMUP;
  *repeat = KWS_SMOKE_DEFAULT_REPEAT;

  for (index = 1; index < argc; index++)
    {
      if (strcmp(argv[index], "--warmup") == 0 && index + 1 < argc)
        {
          if (kws_smoke_parse_count(argv[++index], KWS_SMOKE_MAX_REPEAT,
                                    warmup) < 0)
            {
              return -EINVAL;
            }
        }
      else if (strcmp(argv[index], "--repeat") == 0 && index + 1 < argc)
        {
          if (kws_smoke_parse_count(argv[++index], KWS_SMOKE_MAX_REPEAT,
                                    repeat) < 0 || *repeat == 0)
            {
              return -EINVAL;
            }
        }
      else if (strcmp(argv[index], "--help") == 0 ||
               strcmp(argv[index], "-h") == 0)
        {
          kws_smoke_usage(argv[0]);
          return 1;
        }
      else
        {
          return -EINVAL;
        }
    }

  return 0;
}

static int kws_smoke_tensor_elements(const TfLiteTensor *tensor)
{
  int count = 1;
  int index;

  if (tensor == NULL || tensor->dims == NULL)
    {
      return 0;
    }

  for (index = 0; index < tensor->dims->size; index++)
    {
      count *= tensor->dims->data[index];
    }

  return count;
}

static uint64_t kws_smoke_monotonic_us(void)
{
  struct timespec time;

  if (clock_gettime(CLOCK_MONOTONIC, &time) < 0)
    {
      return 0;
    }

  return (uint64_t)time.tv_sec * UINT64_C(1000000) +
         (uint64_t)time.tv_nsec / UINT64_C(1000);
}

static int kws_smoke_compare_u32(const void *left, const void *right)
{
  uint32_t a = *(const uint32_t *)left;
  uint32_t b = *(const uint32_t *)right;

  return (a > b) - (a < b);
}

static void kws_smoke_fill_input(TfLiteTensor *input)
{
  int index;

  for (index = 0; index < KWS_SMOKE_FEATURE_SIZE; index++)
    {
      input->data.int8[index] =
        (int8_t)(((uint32_t)index * UINT32_C(37) + UINT32_C(19)) >> 1);
    }
}

static void kws_smoke_print_output(const TfLiteTensor *output)
{
  static const char *const labels[KWS_SMOKE_CLASS_COUNT] =
  {
    "wake", "hard_neg", "other_speech", "background", "silence"
  };
  int index;

  printf("[kws_smoke] output");
  for (index = 0; index < KWS_SMOKE_CLASS_COUNT; index++)
    {
      float score = (output->data.int8[index] - output->params.zero_point) *
                    output->params.scale;
      printf(" %s=%.4f", labels[index], (double)score);
    }

  printf("\n");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

extern "C" int kws_smoke_main(int argc, char *argv[])
{
  tflite::MicroMutableOpResolver<9> resolver;
  const tflite::Model *model;
  TfLiteTensor *input;
  TfLiteTensor *output;
  unsigned int warmup;
  unsigned int repeat;
  unsigned int run;
  uint64_t total_us = 0;
  int ret;

  ret = kws_smoke_parse_options(argc, argv, &warmup, &repeat);
  if (ret != 0)
    {
      if (ret < 0)
        {
          kws_smoke_usage(argv[0]);
        }

      return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
    }

  model = tflite::GetModel(g_s3_model);
  if (model == NULL || model->version() != TFLITE_SCHEMA_VERSION)
    {
      fprintf(stderr, "[kws_smoke] model schema mismatch: model=%d runtime=%d\n",
              model == NULL ? -1 : model->version(), TFLITE_SCHEMA_VERSION);
      return EXIT_FAILURE;
    }

  if (resolver.AddShape() != kTfLiteOk ||
      resolver.AddStridedSlice() != kTfLiteOk ||
      resolver.AddPack() != kTfLiteOk ||
      resolver.AddReshape() != kTfLiteOk ||
      resolver.AddConv2D() != kTfLiteOk ||
      resolver.AddDepthwiseConv2D() != kTfLiteOk ||
      resolver.AddMean() != kTfLiteOk ||
      resolver.AddFullyConnected() != kTfLiteOk ||
      resolver.AddSoftmax() != kTfLiteOk)
    {
      fprintf(stderr, "[kws_smoke] required operator registration failed\n");
      return EXIT_FAILURE;
    }

  printf("[kws_smoke] model_bytes=%u schema=%d operators=9 backend=reference\n",
         g_s3_model_len, model->version());
  printf("[kws_smoke] arena_reserved=%u address=%p aligned_16=%d\n",
         (unsigned int)sizeof(g_tensor_arena), g_tensor_arena,
         ((uintptr_t)g_tensor_arena & 0x0f) == 0);

  tflite::MicroInterpreter interpreter(model, resolver, g_tensor_arena,
                                        sizeof(g_tensor_arena));
  if (interpreter.AllocateTensors() != kTfLiteOk)
    {
      fprintf(stderr, "[kws_smoke] AllocateTensors failed; arena=%u\n",
              (unsigned int)sizeof(g_tensor_arena));
      return EXIT_FAILURE;
    }

  input = interpreter.input(0);
  output = interpreter.output(0);
  if (input == NULL || output == NULL || input->type != kTfLiteInt8 ||
      output->type != kTfLiteInt8 ||
      kws_smoke_tensor_elements(input) != KWS_SMOKE_FEATURE_SIZE ||
      kws_smoke_tensor_elements(output) != KWS_SMOKE_CLASS_COUNT)
    {
      fprintf(stderr,
              "[kws_smoke] tensor contract mismatch: input=%d output=%d "
              "input_type=%d output_type=%d\n",
              kws_smoke_tensor_elements(input), kws_smoke_tensor_elements(output),
              input == NULL ? -1 : (int)input->type,
              output == NULL ? -1 : (int)output->type);
      return EXIT_FAILURE;
    }

  printf("[kws_smoke] tensors input=int8[%d] scale=%.9g zp=%d "
         "output=int8[%d] scale=%.9g zp=%d arena_used=%u\n",
         kws_smoke_tensor_elements(input), (double)input->params.scale,
         input->params.zero_point, kws_smoke_tensor_elements(output),
         (double)output->params.scale, output->params.zero_point,
         (unsigned int)interpreter.arena_used_bytes());

  kws_smoke_fill_input(input);
  for (run = 0; run < warmup; run++)
    {
      if (interpreter.Invoke() != kTfLiteOk)
        {
          fprintf(stderr, "[kws_smoke] warmup invoke %u failed\n", run + 1);
          return EXIT_FAILURE;
        }
    }

  for (run = 0; run < repeat; run++)
    {
      uint64_t start = kws_smoke_monotonic_us();
      uint64_t end;

      if (interpreter.Invoke() != kTfLiteOk)
        {
          fprintf(stderr, "[kws_smoke] timed invoke %u failed\n", run + 1);
          return EXIT_FAILURE;
        }

      end = kws_smoke_monotonic_us();
      if (start == 0 || end < start || end - start > UINT32_MAX)
        {
          fprintf(stderr, "[kws_smoke] monotonic timing unavailable\n");
          return EXIT_FAILURE;
        }

      g_invoke_us[run] = (uint32_t)(end - start);
      total_us += g_invoke_us[run];
    }

  qsort(g_invoke_us, repeat, sizeof(g_invoke_us[0]), kws_smoke_compare_u32);
  printf("[kws_smoke] invoke_us warmup=%u repeat=%u min=%" PRIu32
         " p50=%" PRIu32 " mean=%" PRIu64 " p95=%" PRIu32
         " max=%" PRIu32 "\n",
         warmup, repeat, g_invoke_us[0],
         g_invoke_us[(repeat - 1) / 2], total_us / repeat,
         g_invoke_us[(repeat * 95 + 99) / 100 - 1],
         g_invoke_us[repeat - 1]);
  kws_smoke_print_output(output);
  return EXIT_SUCCESS;
}
